-- Database: Soto Semarang Tan Nyana
CREATE DATABASE IF NOT EXISTS soto_tan_nyana CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE soto_tan_nyana;

DROP TABLE IF EXISTS transaksi_detail;
DROP TABLE IF EXISTS transaksi;
DROP TABLE IF EXISTS menu;
DROP TABLE IF EXISTS users;

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  username VARCHAR(50) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  nama VARCHAR(100) NOT NULL
) ENGINE=InnoDB;

-- Password awal = kasir123 (disimpan sebagai SHA-256, otomatis diubah ke bcrypt saat login pertama)
