CREATE TABLE menu (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  harga INT NOT NULL,
  ikon VARCHAR(10) NOT NULL DEFAULT '🍢',
  gambar MEDIUMBLOB NULL,
  gambar_tipe VARCHAR(20) NULL,
  is_soto TINYINT(1) NOT NULL DEFAULT 0,
  aktif TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB;

