INSERT INTO transaksi_detail (transaksi_id, menu_id, nama, harga, qty, is_soto)
SELECT t.id, m.id, m.nama, m.harga, d.qty, m.is_soto FROM (
  SELECT 'TRX-0000' k,'Soto Besar' n,2 qty UNION ALL
  SELECT 'TRX-0001','Soto Besar',1 UNION ALL SELECT 'TRX-0001','Es Teh',1 UNION ALL
  SELECT 'TRX-0002','Soto Besar',1 UNION ALL SELECT 'TRX-0002','Sate Puyuh',3 UNION ALL
  SELECT 'TRX-0003','Soto Besar',1 UNION ALL SELECT 'TRX-0003','Es Teh',1 UNION ALL SELECT 'TRX-0003','Sate Puyuh',1 UNION ALL
  SELECT 'TRX-0004','Soto Besar',3 UNION ALL
  SELECT 'TRX-0005','Soto Besar',1 UNION ALL
  SELECT 'TRX-0008','Soto Besar',1 UNION ALL SELECT 'TRX-0008','Tahu Goreng',1 UNION ALL
  SELECT 'TRX-0009','Soto Besar',1 UNION ALL SELECT 'TRX-0009','Soto Kecil',1 UNION ALL SELECT 'TRX-0009','Sate Ati',1
) d JOIN transaksi t ON t.kode=d.k JOIN menu m ON m.nama=d.n;

